// 逐半日/终止的持久形状风险门；真正服务付款、伤因、死亡来源由后续完整来源核验。
#include "resident/domains/growth/growth_recovery_model.hpp"
#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {int checks=0;void check(bool v,const char* s){++checks;if(!v)throw std::runtime_error(s);}}
int main(){try{
    GrowthRecoveryState s;s.services.insert("action:1",{"patient","provider","role","place",GrowthRecoveryMethod::safe_lodging,4,2,{}});GrowthRecoveryStep step;step.action_id="action:1";step.tick=5;step.ordinal=1;step.before={1,0};step.after={1,1};step.offered_points=step.used_points=1;s.credits.insert("recovery:2",step);check(validate_growth_recovery_shape(s).ok,"real first half-day credit shape");auto bad=s;bad.credits.find("recovery:2")->after.injury=0;check(!validate_growth_recovery_shape(bad).ok,"one lodging half-day cannot cure a whole grade");bad=s;bad.credits.insert("recovery:3",step);check(!validate_growth_recovery_shape(bad).ok,"same ordinal not credited twice");bad=s;bad.credits.find("recovery:2")->tick=6;check(!validate_growth_recovery_shape(bad).ok,"elapsed time not detached from actual half-day ordinal");
    GrowthRecoveryClosure close;close.action_id="action:1";close.tick=5;close.provided_half_days=1;close.reason="cancelled";s.closures.insert("recovery:3",close);check(validate_growth_recovery_shape(s).ok,"cancel preserves one actual half-day without future credit");bad=s;bad.closures.find("recovery:3")->reason="patient_dead";check(!validate_growth_recovery_shape(bad).ok,"death cannot be inferred without its exact source");bad.closures.find("recovery:3")->cause_fact_id="military:4";check(validate_growth_recovery_shape(bad).ok,"death reference shape only not yet a true source proof");bad=s;bad.closures.insert("recovery:4",close);check(!validate_growth_recovery_shape(bad).ok,"one original action cannot be stopped twice");bad=s;bad.closures.find("recovery:3")->reason="completed";check(!validate_growth_recovery_shape(bad).ok,"partial cancelled service cannot pretend full delivery");bad=s;bad.closures.find("recovery:3")->cause_fact_id="invented";check(!validate_growth_recovery_shape(bad).ok,"cancel cannot borrow a death cause");bad=s;bad.field_order={"version","services","credits","credits"};check(!validate_growth_recovery_shape(bad).ok,"duplicate root field order rejected");
    std::cout<<"GROWTH_RECOVERY_SHAPE "<<checks<<" checks 0 failures\n";return 0;
}catch(const std::exception& e){std::cerr<<"GROWTH_RECOVERY_SHAPE "<<checks<<" checks 1 failure: "<<e.what()<<'\n';return 1;}}
